class AuctionSystem {
  private final java.util.Map<Long, Integer> bids = new java.util.HashMap<>();
  private final java.util.Map<Integer, java.util.TreeSet<Long>> byItem = new java.util.HashMap<>();

  public AuctionSystem() {}

  private static long key(int user, int item) {
    return (long) user * 100_000 + item;
  }

  public void addBid(int userId, int itemId, int bidAmount) {
    Integer old = bids.put(key(userId, itemId), bidAmount);
    java.util.TreeSet<Long> set = byItem.computeIfAbsent(itemId, k -> new java.util.TreeSet<>());
    if (old != null) set.remove(((long) old << 20) | userId);
    set.add(((long) bidAmount << 20) | userId);
  }

  public void updateBid(int userId, int itemId, int newAmount) {
    addBid(userId, itemId, newAmount);
  }

  public void removeBid(int userId, int itemId) {
    Integer old = bids.remove(key(userId, itemId));
    if (old != null) byItem.get(itemId).remove(((long) old << 20) | userId);
  }

  public int getHighestBidder(int itemId) {
    java.util.TreeSet<Long> set = byItem.get(itemId);
    if (set == null || set.isEmpty()) return -1;
    return (int) (set.last() & ((1 << 20) - 1));
  }
}
